def _normalize_tags(items: list[tuple[str, str]]) -> list[tuple[str, str]]:
    seen: dict[str, str] = {}
    for industry, source in items:
        cleaned = industry.strip()
        if not cleaned:
            continue
        if cleaned not in seen or seen[cleaned] == "keyword_rule":
            seen[cleaned] = source
    return sorted(seen.items(), key=lambda x: x[0])


def _build_news_text(*, keyword: str, title: str, summary: str) -> str:
    return " ".join(part for part in [keyword.strip(), title.strip(), summary.strip()] if part)


def _extract_candidate_codes_from_text(conn: sqlite3.Connection, text: str) -> set[str]:
    codes = set(_extract_code_candidates(text))
    instruments = _load_instruments(conn)
    for item in instruments:
        if item.full_name and _has_exact_entity_mention(text, item.full_name):
            codes.add(item.code)
        if item.name and _has_exact_entity_mention(text, item.name):
            codes.add(item.code)
    return codes


def _industries_from_codes(conn: sqlite3.Connection, codes: set[str]) -> set[str]:
    if not codes:
        return set()
    placeholders = ",".join(["?"] * len(codes))
    rows = conn.execute(
        f"SELECT DISTINCT industry FROM instruments WHERE code IN ({placeholders})",
        tuple(sorted(codes)),
    ).fetchall()
    return {str(row["industry"]).strip() for row in rows if str(row["industry"]).strip()}


def _keyword_rule_industries(conn: sqlite3.Connection, text: str) -> set[str]:
    if not text.strip():
        return set()
    lowered = text.lower()
    hits: set[str] = set()
    for industry, keywords in _INDUSTRY_KEYWORD_RULES:
        if any(keyword.lower() in lowered for keyword in keywords):
            hits.add(industry)
    return hits


def _derive_news_industry_tags(
    conn: sqlite3.Connection,
    *,
