    title: str,
    summary: str,
    mapped_industries: list[str] | None = None,
    runtime: IndustryTaggingRuntimeStats | None = None,
) -> list[tuple[str, str]]:
    dictionary_names = _ensure_industry_dictionary(conn, runtime)

    if mapped_industries:
        if dictionary_names:
            for industry in mapped_industries:
                if industry.strip() and industry.strip() not in dictionary_names and runtime:
                    runtime.instrument_map_out_of_dictionary_count += 1
        return _normalize_tags([(industry, "instrument_map") for industry in mapped_industries])

    text = _build_news_text(keyword=keyword, title=title, summary=summary)
    mapped = _industries_from_codes(conn, _extract_candidate_codes_from_text(conn, text))
    if mapped:
        if dictionary_names:
            for industry in mapped:
                if industry.strip() and industry.strip() not in dictionary_names and runtime:
                    runtime.instrument_map_out_of_dictionary_count += 1
        return _normalize_tags([(industry, "instrument_map") for industry in mapped])

    fallback = _keyword_rule_industries(conn, text)
    if dictionary_names is not None:
        filtered: set[str] = set()
