        return re.match(r"[0-9A-Za-z\u4e00-\u9fff]", ch) is not None

    start = 0
    while True:
        idx = text.find(entity, start)
        if idx < 0:
            return False
        end = idx + len(entity)

        left_ok = idx == 0
        if not left_ok:
            prev = text[idx - 1]
            left_ctx = text[max(0, idx - 2) : idx]
            left_ok = (not _is_word_char(prev)) or (left_ctx in allow_left_ctx)

        right_ok = end >= len(text)
