from __future__ import annotations

import sqlite3
import time
from dataclasses import dataclass

from rich.console import Console

from .fetchers import (
    fetch_announcements_for_stock_stats,
    fetch_global_announcements_stats,
    fetch_global_news_stats,
    fetch_news_for_stock_stats,
    fetch_global_news_stats,
    format_announcements_sync_stats,
    format_global_announcements_sync_stats,
    format_global_news_sync_stats,
    format_news_sync_stats,
)
from .storage import list_retryable_failures, record_failure, resolve_failure


@dataclass(slots=True)
class ScheduleConfig:
    interval_minutes: int = 30


def _run_single_task(conn: sqlite3.Connection, task_name: str, code: str) -> str:
    if task_name == "announcements":
        return format_announcements_sync_stats(fetch_announcements_for_stock_stats(conn, code))
    if task_name == "news":
        return format_news_sync_stats(fetch_news_for_stock_stats(conn, code))
    if task_name == "global_news":
        return format_global_news_sync_stats(fetch_global_news_stats(conn, request_key=code))
    raise ValueError(f"unknown task: {task_name}")


def run_once(conn: sqlite3.Connection, console: Console, codes: list[str]) -> None:
    retry_rows = list_retryable_failures(conn)
    for item in retry_rows:
